/**
 * ✅ 단원 자동 인식 (강화)
 * 우선순위: ?unit=geo_XX → 파일명 geo_XX.html → 제목 숫자
 */
(function () {
  // 이미 설정된 CUR_UNIT이 있고, geo_로 시작하면 덮어쓰지 않음
  if (window.CUR_UNIT && window.CUR_UNIT.startsWith('deep_geo_')) {
    console.log('[deep_geo_content.js] CUR_UNIT 이미 설정됨:', window.CUR_UNIT);
    return;
}

  const qs = new URLSearchParams(location.search).get('unit');
  let unit = null;

  if (qs) {
    const m = qs.toLowerCase().match(/deep_geo[_-]?(\d{1,2})/);
    if (m) unit = `deep_geo_${m[1].padStart(2, '0')}`;
}

  if (!unit) {
    const m2 = location.pathname.toLowerCase().match(/deep_geo[_-]?(\d{1,2})\.html/);
    if (m2) unit = `deep_geo_${m2[1].padStart(2, '0')}`;
}

  if (!unit && document.title) {
    const m3 = document.title.match(/(\d{1,2})/);
    if (m3) unit = `deep_geo_${m3[1].padStart(2, '0')}`;
}

  window.CUR_UNIT = unit || 'deep_geo_01';
})();

/* ===============================
   ✅ 전역 CONTENTS 준비 (단일화)
   =============================== */
window.CONTENTS = window.CONTENTS || {};

