    passage: [
      '한반도의 지형은 수억 년에 걸친 <b>지각 변동</b>과 <b>침식</b>, 퇴적 작용의 누적된 결과물이다. 한반도의 기반암은 대부분 선캄브리아기에 형성된 변성암과 화강암으로 이루어져 있으며, 이는 약 25억 년 전부터 5억 년 전 사이에 만들어진 매우 오래된 지층으로 평안남도와 강원도 일대에 널리 분포한다. 이후 고생대에는 바다에 잠겨 평안 누층군에 속하는 석회암과 사암이 퇴적되었고, 이 시기의 석회암은 오늘날 강원도 영월·정선의 카르스트 지형과 시멘트 산업의 토대가 되었다. 중생대에는 격렬한 화산 활동과 <b>조산 운동</b>이 일어나 송림 변동, 대보 조산 운동을 거치면서 지금의 산지 골격이 형성되기 시작했다. 특히 중생대 말부터 신생대 초의 <b>경동성 요곡 운동</b>은 한반도 지형의 핵심적인 특징인 동고서저의 비대칭 지형을 만들어 냈다. 동쪽이 솟아오르고 서쪽이 낮아지면서, 동해안은 급경사의 해안 절벽이, 서해안은 완만한 갯벌과 리아스식 해안이 발달하게 되었다.',
      '신생대 제3기에는 비교적 안정된 시기가 지속되면서 오랜 세월에 걸쳐 <b>풍화</b>와 침식 작용이 진행되었고, 이로 인해 <b>고위 평탄면</b>이 형성되었다. 고위 평탄면은 해발 고도가 높은 산지 위에 평평하게 남아 있는 옛 지표면으로, 강원도의 대관령, 진부령, 육백산 고원 등이 대표적이며 해발 700~1,000m 내외의 높이에 펼쳐져 있다. 이러한 고위 평탄면은 현재 고랭지 농업과 목축업에 활용되고 있다. 여름철 서늘한 기후를 활용한 배추, 무 재배와 평창의 한우 목장이 유명하다. 신생대 제4기에는 백두산과 제주도, 울릉도, 독도 등에서 화산 활동이 일어나 화산 지형이 형성되었다. 백두산의 천지는 화산 폭발 후 칼데라에 물이 고여 만들어진 동양 최대의 <b>칼데라호</b>이며, 제주도의 한라산은 순상 화산으로 완만한 경사를 이루고, 섬 곳곳에 360여 개의 오름(기생 화산)이 분포하여 독특한 화산 경관을 형성한다.',
      '한반도의 산지는 <b>1차 산맥</b>과 <b>2차 산맥</b>으로 구분된다. 1차 산맥은 지각 변동에 의해 형성된 산맥으로 낭림산맥, 태백산맥, 함경산맥이 있으며, 한반도의 등뼈 역할을 한다. 이들 산맥은 높고 험준하며 하천의 <b>분수령</b> 역할을 수행한다. 반면 2차 산맥은 1차 산맥에서 갈라져 나온 산맥으로, 차령산맥, 소백산맥, 노령산맥 등이 있다. 2차 산맥은 상대적으로 낮고 완만하여 교통로와 취락이 발달하기 용이하다. 실제로 추풍령, 죽령, 조령 같은 고개는 예부터 영남과 호남을 잇는 주요 교통로로 활용되어 왔다. 한반도 지형의 특징적 구조는 북동쪽에서 남서쪽으로 지대가 낮아지는 <b>동고서저</b>, 산지가 북쪽에 집중되어 있는 북고남저의 경향을 뚜렷하게 보인다.',
      '하천 지형 역시 이러한 지형 구조의 영향을 직접적으로 받는다. 동쪽 사면의 하천은 짧고 경사가 급하여 유속이 빠른 반면, 서쪽 사면의 한강, 낙동강, 금강, 영산강과 같은 큰 하천은 길고 완만하여 넓은 <b>충적 평야</b>가 발달했다. 주요 하천의 중·하류에는 김포평야, 호남평야, 김해평야 같은 범람원과 삼각주가 형성되어 농경지와 인구가 집중되는 공간이 되었다. 해안 지형에서도 동해안과 서·남해안의 차이가 뚜렷하다. 동해안은 단조로운 사빈 해안과 경포호, 송지호 같은 <b>석호</b>가 발달했고, 서·남해안은 복잡한 <b>리아스식 해안</b>과 넓은 <b>갯벌</b>이 특징이다. 새만금과 시화호처럼 갯벌을 간척하여 농지와 산업 단지로 활용한 대규모 사례도 많아, 지형이 산업 활동의 토대가 되었음을 잘 보여 준다. 이처럼 한반도의 지형은 수억 년에 걸친 지질 시대의 역사를 담고 있으며, 각 지역의 산업과 생활 방식, 문화 형성에까지 깊은 영향을 미쳐 왔다.'
    ],
