    labelNo: '05',
    title: '☀️ 기후가 삶을 결정한다',
    paragraphMain: [
      '기후 요소: 기온·강수량·바람·습도가 지역의 농업·의복·주거에 미치는 영향을 알아보다',
      '기후 요인: 위도·수륙 분포·해발 고도가 기온과 연교차에 미치는 영향을 이해하다',
      '온대 계절풍 기후: 우리나라의 사계절과 여름 강수 집중, 벼농사·발효 음식·온돌 문화 형성',
      '기후와 인간 생활: 쾨펜의 기후 구분, 지역별 주거 형태, 기후 변화로 인한 전 지구적 위협'
    ],
    passage: [
      '<b>기후</b>는 특정 지역에서 오랜 기간에 걸쳐 나타나는 대기 상태의 평균적인 특성을 의미하며, 날씨가 짧은 시간의 기상 현상이라면 기후는 통상 30년 이상의 장기적인 경향을 말한다. 세계기상기구(WMO)도 30년 평균을 기후의 표준 단위로 삼고 있다. 기후를 구성하는 <b>기후 요소</b>에는 <b>기온</b>, <b>강수량</b>, 바람, 습도 등이 있다. 기온은 대기의 온도로, 지역의 농업 방식과 의복, 주거 형태에 영향을 미친다. 강수량은 일정 기간 동안 내린 비나 눈의 양으로, 물 자원의 확보와 농업 생산성을 좌우한다. 바람은 대기의 흐름으로, 항해와 풍력 발전, 황사나 미세먼지의 이동에까지 활용되며, 습도는 공기 중 수증기의 양으로 체감 온도와 쾌적성에 영향을 준다. 이러한 기후 요소들은 서로 긴밀히 상호작용하며 지역의 기후 특성을 형성한다.',
      '기후 요소에 영향을 주는 조건을 <b>기후 요인</b>이라 하며, <b>위도</b>, <b>수륙 분포</b>, 해발 고도, 지형, 해류 등이 있다. 위도는 기후에 가장 큰 영향을 미치는 요인으로, 적도에 가까울수록 태양 복사 에너지를 많이 받아 기온이 높고, 극지방으로 갈수록 기온이 낮아진다. 수륙 분포는 바다와 육지의 비열 차이로 인해 해안 지역과 내륙 지역의 기온 차이를 만든다. 바다는 비열이 커서 천천히 데워지고 천천히 식으므로 해안 지역은 <b>기온의 연교차</b>가 작고, 내륙 지역은 연교차가 크다. 예를 들어 같은 위도라도 부산의 연교차는 약 25°C인 반면, 내륙인 대구나 청주는 30°C에 가깝다. 해발 고도가 높아지면 기온이 낮아지는데, 일반적으로 100m 상승할 때마다 약 0.6°C씩 기온이 하강하여 한라산 정상은 같은 제주 시내보다 평균 10°C 이상 낮다.',
      '우리나라의 기후는 <b>온대 계절풍 기후</b>로, 사계절이 뚜렷하게 나타나는 것이 특징이다. 여름에는 북태평양 기단에서 발달한 고온 다습한 <b>남동 계절풍</b>이 불어 무덥고 비가 많이 오며, 겨울에는 시베리아 기단에서 내려오는 한랭 건조한 <b>북서 계절풍</b>이 불어 춥고 건조한 삼한사온 현상이 나타난다. 이러한 계절풍의 영향으로 여름과 겨울의 기온 차가 크고, 강수량의 계절적 편차도 심하다. 특히 6~9월의 강수량이 연 강수량의 50~60%를 차지하여 여름 강수 집중 현상이 나타난다. 또한 <b>장마</b>와 <b>태풍</b>의 영향으로 집중 호우가 발생하기도 한다. 이러한 기후 특성은 벼농사 중심의 농업 발달, 김치와 된장 같은 발효 음식 문화, 온돌 난방과 대청마루의 이중 구조 등 독특한 생활 양식을 형성하는 데 기여했다.',
      '기후는 인간 생활 전반에 깊은 영향을 미친다. 농업에서는 재배 작물의 종류와 수확 시기, 농법이 기후에 따라 달라지며, <b>쾨펜의 기후 구분</b>은 식생 분포와 농업 활동을 기준으로 세계의 기후를 체계적으로 분류한다. 건축에서도 기후는 중요한 고려 요소로, 열대 지역의 고상 가옥, 건조 지역의 흙벽돌집, 한대 지역의 이글루 등은 각 지역의 기후에 적응한 주거 형태이다. 의복 문화 역시 기후의 영향을 받아 열대 지역에서는 통풍이 잘 되는 얇은 옷을, 한대 지역에서는 보온성이 높은 모피 옷을 입는다. 오늘날 <b>기후 변화</b>는 전 지구적 문제로 대두되고 있으며, 산업 혁명 이후 화석 연료 사용으로 대기 중 이산화탄소 농도가 급격히 증가했다. 이로 인한 지구 온난화는 해수면 상승으로 투발루 같은 섬나라를 위협하고, 폭염과 한파, 산불, 가뭄 같은 극단적 기상 현상의 증가와 생태계 변화, 식량 안보 위기 등이 심각한 위협으로 다가오고 있다. 이에 파리 협정 같은 국제 사회의 공동 대응과 탄소 중립 정책이 시급한 과제로 떠오르고 있다.'
    ],
