      q5:'주택 문제는 공공 임대 주택 확대와 신도시 개발로, 교통 혼잡은 대중교통 확충과 교통 수요 관리로, 환경 오염과 열섬 현상은 녹지 공간 확보와 생태 도시 조성으로 해결할 수 있다. 궁극적으로 스마트 시티를 통해 교통, 에너지, 환경을 효율적으로 관리하는 지속 가능한 도시를 추구해야 한다.'
