    passage: [
      '<b>자원</b>은 인간 생활과 경제 활동에 필요한 물질을 말하며, 크게 에너지 자원, 광물 자원, 생물 자원으로 구분된다. 자원의 가치는 고정적이지 않고 기술 발전, 경제 상황, 대체재 출현 등에 따라 변화한다. 과거에는 가치가 없던 물질이 기술 발전으로 중요한 자원이 되기도 하며, 이를 자원의 가변성이라 한다. 셰일가스나 희토류가 대표적인 사례로, 채굴 기술의 발달과 첨단 산업의 수요 증가에 따라 자원의 가치가 새롭게 부여되었다. 또한 자원은 지구상에 고르게 분포하지 않아 <b>편재성</b>을 띠는데, 이로 인해 자원 부국과 빈국 간의 갈등이 발생하기도 한다. 특히 화석 연료인 석유, <b>석탄</b>, 천연가스는 특정 지역에 집중되어 있어 국제 정세와 밀접하게 연관된다. 우리나라는 에너지 자원의 대부분을 수입에 의존하고 있어 에너지 안보 문제가 중요한 국가적 과제이다.',
      '화석 연료는 산업혁명 이후 인류 문명을 지탱해 온 핵심 에너지원이다. 석탄은 18세기 영국 산업혁명의 원동력이었으며, 현재도 호주, 인도네시아, 러시아 등에서 생산되어 화력 발전의 주요 연료로 사용된다. <b>석유</b>는 20세기 이후 교통, 화학 공업의 핵심 자원으로 부상했고, 사우디아라비아, 이라크, 이란 등 중동 지역에 전 세계 매장량의 약 50%가 집중되어 있다. <b>천연가스</b>는 석탄이나 석유보다 이산화탄소 배출이 적은 청정한 연료로 난방과 발전, LNG 수송 등에 널리 쓰인다. 그러나 화석 연료는 사용 시 이산화탄소를 배출하여 지구 온난화를 유발하고, 매장량이 한정되어 있는 고갈성 자원이라는 한계가 있다. 현재의 소비 추세가 지속된다면 석유는 약 50년, 천연가스는 약 50년, 석탄은 약 130년 내에 고갈될 것으로 전망된다.',
      '환경 문제와 자원 고갈에 대응하여 <b>신재생에너지</b>에 대한 관심이 높아지고 있다. 태양광 에너지는 태양빛을 전기로 변환하며, 설치 비용이 낮아지면서 급속히 보급되고 있다. 풍력 에너지는 바람의 힘으로 터빈을 돌려 전기를 생산하며, 제주도와 영광의 해상 풍력 발전이 새로운 성장 동력으로 주목받고 있다. 수력 에너지는 물의 낙차를 이용한 발전으로 오랜 역사를 가지고 있다. 그 외에도 지열, 조력, 바이오매스 등 다양한 재생에너지가 개발되고 있는데, 충남 당진의 조력 발전소가 그 예시이다. 신재생에너지는 탄소 배출이 적고 무한히 재생 가능하다는 장점이 있으나, 초기 투자 비용이 높고 자연 조건에 따라 발전량이 변동한다는 단점도 있다.',
      '전 세계적으로 에너지 전환이 가속화되고 있다. 2015년 채택된 파리기후협약 이후 각국은 탄소 배출을 줄이기 위해 <b>탄소중립</b> 목표를 설정하고 재생에너지 비중 확대에 나서고 있다. 우리나라도 2050년 탄소중립을 선언하고 재생에너지 발전 비중을 높이는 정책을 추진하고 있다. 한편 원자력 에너지는 발전 과정에서 탄소를 배출하지 않아 청정에너지로 분류되기도 하지만, 방사성 폐기물 처리와 안전성 문제로 논쟁이 계속되고 있다. 독일은 탈원전을 추진하며 재생에너지 비중을 빠르게 높이고 있고, 프랑스는 원자력 중심의 에너지 구조를 유지하고 있어 국가별 선택지가 다양함을 보여 준다. 미래 에너지 체제는 화석 연료 의존에서 벗어나 재생에너지와 원자력, 수소 에너지 등을 조합한 에너지 믹스로 전환될 전망이다. 최근에는 전기차 보급 확대, 수소 충전 인프라 구축, 스마트 그리드를 통한 에너지 효율화 등 새로운 기술과 시스템이 빠르게 자리 잡고 있다. 에너지 문제는 환경, 경제, 안보가 복합적으로 얽힌 문제로, 정부와 기업, 시민 사회가 함께 협력하여 절약과 효율화에 앞장설 때 비로소 지속 가능한 발전을 이룰 수 있다.'
    ],
