    title: '🌐 세계가 하나로 연결되다',
    paragraphMain: [
      '세계화의 촉진: 교통·통신 발달과 다국적 기업 성장, WTO와 국제무역 30배 증가의 순기능',
      '세계화의 문제점: 경제적 불평등 심화, 문화 획일화와 문화제국주의, 전염 효과의 위험',
      '지역화의 의미: 고유 문화 보존과 로컬푸드 운동, 지리적 표시제와 세계문화유산 보호',
      '세방화 전략: 세계화와 지역화의 조화, 장소 마케팅으로 지역 고유성이 경쟁력이 되다'
    ],
    passage: [
      '<b>세계화</b>는 국경을 넘어 정치, 경제, 사회, 문화의 상호 의존성과 연결성이 심화되는 현상이다. 컨테이너선과 항공 화물, 인터넷 같은 교통과 통신 기술의 발달, 무역 장벽의 완화, 삼성과 애플, 도요타 같은 다국적 기업의 성장 등이 세계화를 촉진했다. 오늘날 우리는 아침에 콜롬비아산 커피를 마시고, 중국에서 조립되고 한국 부품이 들어간 스마트폰을 사용하며, 미국 드라마와 일본 애니메이션을 스트리밍으로 시청한다. 국제 무역의 규모는 지난 50년간 약 30배 증가했으며, 자본, 기술, 정보가 국경을 초월하여 자유롭게 이동한다. <b>세계무역기구</b>(WTO)는 자유 무역을 촉진하고 무역 분쟁을 해결하는 국제기구로, 세계화의 제도적 기반을 제공한다. 세계화는 전 세계를 하나의 네트워크로 연결하여 경제적 효율성을 높이고 문화 교류를 활성화하는 순기능을 가진다.',
      '그러나 세계화는 다양한 문제점도 수반한다. 선진국과 개발도상국 간의 경제적 불평등이 심화되는 경향이 있다. 다국적 기업은 베트남, 방글라데시 같은 저임금 국가에서 생산하여 고소득 국가에 판매함으로써 이윤을 극대화하지만, 이 과정에서 개발도상국 노동자들의 열악한 노동 환경 문제가 발생하기도 한다. 2013년 방글라데시 라나 플라자 봉제 공장 붕괴 사고가 대표적이다. 또한 세계화는 문화 획일화를 초래한다는 비판도 받는다. 미국 헐리우드 영화, 패스트푸드 체인, 글로벌 브랜드가 전 세계로 확산되면서 각 지역의 고유한 문화가 위축되는 문화 제국주의 현상이 나타날 수 있다. 또한 한 지역의 경제 위기가 전 세계로 전파되는 전염 효과도 세계화의 위험 요소이다. 2008년 미국 서브프라임 모기지에서 시작된 금융위기가 전 세계 경제를 침체시킨 것이 대표적인 사례이다.',
      '<b>지역화</b>는 세계화에 대응하여 지역의 고유한 특성과 정체성을 강화하려는 움직임이다. 지역 고유의 문화, 언어, 전통을 보존하고 발전시키며, 지역 경제의 자립성을 높이려는 노력이 이에 해당한다. 로컬 푸드 운동은 지역에서 생산된 농산물을 지역에서 소비하자는 운동으로, 운송 과정의 탄소 배출(푸드 마일리지)을 줄이고 지역 농업을 보호하는 효과가 있다. 지리적 표시제는 보성 녹차, 횡성 한우, 이천 쌀, 프랑스의 샹파뉴(샴페인)처럼 특정 지역의 지리적 특성에 기반한 품질과 명성을 가진 상품을 보호하는 제도이다. 또한 유네스코는 <b>세계문화유산</b>과 인류무형문화유산 제도를 통해 한국의 종묘제례악과 김장 문화 등 각 지역의 고유한 문화와 전통을 보호하고 있다.',
      '세계화와 지역화는 대립적인 것이 아니라 상호 보완적으로 작용할 수 있다. <b>세방화</b>(Glocalization)는 세계화(Globalization)와 지역화(Localization)의 합성어로, 전 지구적 보편성과 지역적 특수성을 조화시키는 전략이다. 맥도날드가 인도에서는 쇠고기 대신 치킨 버거를, 한국에서는 불고기 버거를 판매하는 것이 세방화의 예이다. 스타벅스가 한국 매장에서 인절미와 단호박 음료를 출시하는 것도 같은 맥락이다. 지역은 고유한 정체성을 유지하면서도 세계 시장에서 경쟁력을 확보할 수 있으며, 세계화는 지역의 다양성을 흡수하여 더욱 풍요로워질 수 있다. 지역의 장소 마케팅도 세방화 전략의 일환으로, 지역 고유의 자원과 문화를 활용하여 관광객과 투자를 유치한다. 전주 한옥마을이 전통 한옥 체험과 한복 대여, 비빔밥 거리 등 지역 자원을 활용해 국제적 명소로 자리 잡은 것이 좋은 사례이다. 결국 세계화 시대에 지역의 고유성은 단순한 보존 대상이 아니라 새로운 경쟁력의 원천이 될 수 있다.'
    ],
