    labelNo: '12',
    title: '✈️ 시간과 공간을 넘어',
    paragraphMain: [
      '교통의 혁명: 철도·항공기 발달로 시간 거리와 비용 거리 단축, 접근성 향상과 교류 활성화',
      '통신과 정보화: 원격 근무·전자상거래의 일상화, 공간의 압축과 물리적 공간 중요성 약화',
      '공간 구조 변화: 교통 결절점의 집적과 교외화 현상, 접근성 격차에 따른 지역 불균형',
      '미래 교통·통신: 자율주행차·UAM·메타버스가 바꿀 도시 구조와 경제 활동의 재편'
    ],
    passage: [
      '<b>교통</b>의 발달은 인류의 이동 능력을 혁명적으로 변화시켰다. 과거 도보나 마차에 의존하던 시대에는 하루에 수십 킬로미터 이동이 한계였으나, 19세기 철도 발명을 시작으로 자동차, 항공기의 등장으로 이동 속도와 범위가 비약적으로 확대되었다. <b>고속철도</b>(KTX)는 서울-부산 간 이동 시간을 4시간에서 2시간 30분으로 단축했고, 항공기는 대륙 간 이동을 하루 내에 가능하게 했다. 인천국제공항에서는 매일 300편 이상의 국제선이 운항된다. 이러한 교통 발달은 시간 거리와 비용 거리의 단축을 가져왔다. 시간 거리란 두 지점 간 이동에 소요되는 시간을 의미하며, 교통수단이 발달할수록 물리적 거리가 같아도 시간 거리는 감소한다. 교통 발달은 <b>접근성</b>을 높여 지역 간 교류를 활성화하고 경제 활동의 범위를 확대시켰다.',
      '<b>통신</b>의 발달 또한 공간적 제약을 극복하는 데 결정적인 역할을 했다. 1837년 모스 전신, 19세기 후반 벨의 전화를 거쳐 인터넷과 모바일 통신이 보편화되면서 정보화 사회가 도래했다. 정보화 사회에서는 정보의 생산, 가공, 유통이 경제 활동의 핵심이 되며, 시간과 장소에 구애받지 않고 업무를 수행할 수 있다. 원격 근무와 화상 회의가 일상화되면서 출퇴근 없이도 협업이 가능해졌고, 이는 직주 근접의 필요성을 감소시켰다. 쿠팡, 아마존 같은 <b>전자상거래</b>의 성장은 상권의 개념을 변화시켜 온라인 플랫폼이 전통적인 오프라인 상점을 대체하는 현상도 나타나고 있다. 통신 발달은 물리적 공간의 중요성을 상대적으로 약화시키는 공간의 압축을 가속화하고 있다.',
      '교통·통신의 발달은 공간 구조에 근본적인 변화를 초래했다. 교통 결절점에는 역세권, 공항 인근 등에 상업·업무 기능이 집적되는 현상이 나타난다. 서울역, 용산역 주변의 개발과 인천국제공항 주변 영종도 개발이 대표적이다. 또한 경부고속도로의 김천·구미와 서해안고속도로의 평택·당진처럼 고속도로 인터체인지 주변에는 물류 시설과 공장이 입지하여 산업 단지가 형성되기도 한다. 한편 교통 발달은 <b>교외화</b> 현상을 촉진하여 도심 인구가 분당, 일산, 동탄 같은 주거 환경이 좋은 외곽 지역으로 이동하게 했다. 그러나 교통 인프라가 부족한 지역은 상대적으로 소외되어 지역 간 접근성 격차가 발생한다. 이는 지역 불균형 문제와 연결되어 교통 소외 지역에 대한 정책적 배려가 필요함을 시사한다.',
      '미래 교통·통신 기술은 공간 인식을 더욱 혁신적으로 변화시킬 것이다. <b>자율주행차</b>는 운전에 투입되던 시간을 업무, 휴식, 여가 등 다른 활동에 사용할 수 있게 하여 이동 자체의 의미를 바꿀 것이다. 테슬라와 구글의 웨이모가 자율주행 기술을 선도하고 있으며, 현대차와 카카오모빌리티도 한국형 자율주행 서비스를 개발하고 있다. <b>도심항공교통</b>(UAM)은 수직 이착륙 항공기를 통해 도심 내 3차원 이동을 가능하게 하여 교통 체증 문제를 해결할 대안으로 주목받고 있다. 또한 5G를 넘어 6G 통신으로 진화하면서 <b>메타버스</b>와 같은 가상 공간에서의 활동이 확대될 전망이다. 물리적 이동 없이 가상 공간에서 회의, 교육, 쇼핑, 여가 활동이 이루어지는 미래가 다가오고 있다. 예를 들어 학생은 가상 강의실에서 외국의 친구와 같이 수업을 듣고, 직장인은 해외 동료와 실시간 협업을 진행하며, 환자는 원격 진료를 통해 큰 병원에 가지 않고도 전문의의 상담을 받을 수 있게 된다. 이러한 변화는 도시 구조, 주거 형태, 경제 활동 방식에 근본적인 재편을 가져올 것이며, 디지털 격차 해소와 사이버 보안, 새로운 윤리 기준 마련 등 이에 대응하는 공간 정책의 혁신이 요구된다.'
    ],
