      '건조 기후는 강수량보다 증발량이 많아 물이 부족한 기후로, 사막 기후와 스텝 기후로 구분된다. 사막 기후는 연 강수량 250mm 미만의 극도로 건조한 지역에서 나타나며, 사하라, 아라비아, 고비, 칼라하리 사막 등이 대표적이다. 사막에서는 일교차가 30°C 이상으로 매우 크고 식생이 거의 없으며, <b>오아시스</b> 주변이나 나일강 같은 외래 하천 연안에서만 인간 거주가 가능하다. 고대 이집트 문명도 나일강 유역에서 탄생했다. 스텝 기후는 사막 기후의 주변에 나타나며, 짧은 풀이 자라는 초원이 형성된다. 유목이나 방목이 주된 생업이며, 몽골, 중앙아시아, 미국 대평원이 이에 해당한다. 건조 기후 지역에서는 물 부족과 <b>사막화</b>가 심각한 문제이며, 기후 변화와 과도한 방목·삼림 벌채로 사막화가 더욱 가속화되고 있다.',
      '온대 기후는 사계절이 비교적 뚜렷하고 인간 거주에 적합하여 세계 인구의 상당수가 이 지역에 거주한다. 서안 해양성 기후는 편서풍과 난류의 영향으로 연중 온난하고 강수가 고른 특성을 보이며, 영국·프랑스·독일 같은 서유럽이 대표적이다. 지중해성 기후는 여름에 건조하고 겨울에 강수가 집중되어 이탈리아·그리스·스페인에서 올리브, 포도, 오렌지 등 수목 농업이 발달했다. 온대 계절풍 기후는 계절풍의 영향으로 여름에 고온 다습하고 겨울에 한랭 건조하며, 동아시아, 동남아시아에 분포한다. 우리나라와 중국 동부, 일본도 이 기후에 속하며, 벼농사가 발달했다. 온대 기후 지역은 경제 발전과 도시화가 진행되어 미세먼지와 도시 열섬 같은 환경 오염, 생태계 교란 문제에 직면해 있다.',
      '냉대 기후와 한대 기후는 고위도 지역에 나타난다. 냉대 기후는 겨울이 길고 추우며, <b>타이가</b>라 불리는 침엽수림이 광활하게 펼쳐진다. 러시아의 시베리아, 캐나다, 핀란드와 스웨덴이 있는 스칸디나비아반도가 대표적이다. 타이가 숲은 지구 산소 생산의 중요한 역할을 하며 탄소 흡수원으로도 기능하고, 목재와 펄프 산업의 기반이 된다. 한대 기후는 연중 기온이 매우 낮아 <b>툰드라</b>와 빙설 기후로 구분된다. 툰드라에서는 지의류와 이끼류만 자라며, 순록 유목이 이루어진다. 영구 동토층이 분포하는데, 기후 변화로 영구 동토층이 녹으면서 메탄가스 방출, 지반 침하 등의 문제가 발생하고 있다. 최근 알래스카와 시베리아 일부 지역에서는 영구 동토 위에 세운 건물이 기울거나 도로가 무너지는 사례가 보고되고 있다. 또한 메탄가스 방출은 온실 효과를 더욱 강화시켜 기후 위기를 가속화하는 악순환을 만들고 있다. 기후 변화는 전 지구적 기후대의 변화를 초래하고 있으며, 파리 협정 같은 지속 가능한 발전을 위한 국제 협력이 필수적이다.'
