    title: '🗺️ 디지털 지구를 읽다',
    paragraphMain: [
      '지리 정보의 개념: 위치·속성·관계 정보로 구분되는 지리 정보가 디지털 형태로 일상에 활용되다',
      '지리 정보 기술: GIS의 레이어 중첩 분석, 원격 탐사의 환경 모니터링, GPS의 위치 측정 기술을 살펴보다',
      '다양한 분야 활용: 도시 계획, 환경 관리, 물류, 정밀 농업, 재난 관리에서 의사 결정을 지원하다',
      '미래 기술 융합: 빅데이터·인공지능과 결합하여 디지털 트윈, AR/VR, 자율주행차로 진화하다'
    ],
    passage: [
      '<b>지리 정보</b>는 지표면 위에 존재하는 자연환경과 인문 환경에 관한 정보로, 특정 지점의 위치와 그 장소가 지닌 속성을 포함한다. 지리 정보는 위치 정보, 속성 정보, 관계 정보로 구분되는데, <b>위치 정보</b>는 어떤 대상이 어디에 있는지를 나타내며 위도와 경도, 주소가 대표적이다. <b>속성 정보</b>는 그 대상의 특성이나 성질을 설명하며 도시의 인구, 산업 구조, 기온, 강수량 같은 정보가 해당한다. <b>관계 정보</b>는 여러 대상 간의 공간적 관계를 나타내는 것으로, 예를 들어 특정 지역이 다른 지역과 얼마나 떨어져 있는지, 어떤 경로로 연결되어 있는지 등의 정보를 포함한다. 과거에는 김정호의 대동여지도 같은 종이 지도를 통해 지리 정보를 표현하고 활용했으나, 정보통신기술의 발달로 현재는 디지털 형태의 지리 정보가 광범위하게 활용되고 있다. 카카오맵, 네이버맵, 구글맵 같은 스마트폰 지도 앱, 자동차 내비게이션, 부동산 정보 서비스 등 일상생활 곳곳에서 지리 정보를 접할 수 있다.',
      '<b>지리 정보 시스템</b>(GIS)은 지리 정보를 컴퓨터를 이용하여 수집, 저장, 분석, 표현하는 종합적인 정보 체계이다. GIS의 핵심은 여러 종류의 지리 정보를 <b>레이어</b> 형태로 중첩하여 분석할 수 있다는 점이다. 예를 들어 지형도, 토지이용도, 인구분포도 등을 겹쳐서 보면 특정 지역의 개발 적합성이나 재해 위험성을 종합적으로 판단할 수 있다. <b>원격 탐사</b>는 인공위성이나 항공기 등에 탑재된 센서를 이용하여 지표면의 정보를 원거리에서 수집하는 기술로, 넓은 지역의 환경 변화를 신속하게 파악할 수 있다. 위성 영상을 통해 산림 파괴, 도시 확장, 기후 변화 등을 모니터링하고 분석하는 데 활용된다. <b>위성 위치 확인 시스템</b>(GPS)은 인공위성을 이용하여 지구상의 위치를 정확하게 측정하는 시스템으로, 내비게이션과 위치 기반 서비스의 핵심 기술이다.',
      '지리 정보 기술은 다양한 분야에서 의사 결정을 지원하는 핵심 도구로 활용되고 있다. 도시 계획 분야에서는 GIS를 활용하여 토지 이용 현황 분석, 교통량 예측, 시설 입지 선정 등을 수행한다. 환경 관리 분야에서는 원격 탐사를 통해 오염 실태 파악, 생태계 변화 모니터링, 자연재해 피해 예측 등에 활용한다. 물류와 유통 분야에서는 GPS와 GIS를 결합하여 최적 배송 경로 설정, 차량 위치 추적, 재고 관리 등을 효율화한다. 농업 분야에서는 위성 영상과 드론을 활용한 <b>정밀 농업</b>이 확산되어 농작물 생육 상태 파악, 병충해 조기 발견, 수확량 예측 등이 가능해졌다. 재난 관리 분야에서도 지리 정보 기술은 필수적인데, 홍수, 지진, 산불 등의 재해 발생 시 피해 지역을 신속히 파악하고 구조 활동을 지원하는 데 활용된다.',
      '최근 지리 정보 기술은 <b>빅데이터</b>와 인공지능과 결합하여 더욱 정교해지고 있다. 수많은 위치 데이터를 분석하여 인구 이동 패턴, 상권 분석, 범죄 예방 등 다양한 분야에 활용하고 있다. <b>디지털 트윈</b>은 현실 세계를 디지털 공간에 그대로 구현한 가상 모델로, 도시 관리와 시뮬레이션에 활용된다. 또한 <b>증강 현실</b>(AR)과 <b>가상 현실</b>(VR) 기술과 결합하여 관광, 교육, 부동산 등 분야에서 새로운 경험을 제공하고 있다. <b>자율주행</b> 자동차는 GPS, 라이다, 고정밀 지도 등 다양한 지리 정보 기술을 종합적으로 활용하는 대표적인 사례이다. 지리 정보 기술은 4차 산업혁명 시대의 핵심 기술로서 산업, 행정, 일상생활 등 사회 전반에 걸쳐 영향력을 확대하고 있으며, 개인 위치 데이터의 오남용을 막기 위한 개인정보 보호와 <b>데이터 윤리</b>에 대한 논의도 함께 진행되고 있다.'
    ],
