    title: '⚔️ 국경선에 새겨진 갈등의 역사',
    paragraphMain: [
      '국제 분쟁의 원인: 영토·자원·민족·종교·역사적 배경으로 분쟁이 발생하고 EEZ 해양 경계 갈등이 증가하다',
      '자원 분쟁의 심화: 석유·수자원·광물을 둘러싼 갈등과 북극해 자원 경쟁이 치열해지다',
      '민족·종교 분쟁: 쿠르드족 독립 요구, 이스라엘-팔레스타인, 카슈미르 분쟁 등 정체성 갈등을 살펴보다',
      '분쟁 해결 노력: UN·ICJ·지역 협력체의 중재와 다문화 이해 교육, 평화적 접근의 필요성을 강조하다'
    ],
    passage: [
      '세계 곳곳에서는 다양한 원인으로 <b>국제 분쟁</b>이 발생하고 있다. 분쟁의 원인은 크게 <b>영토 분쟁</b>, 자원을 둘러싼 갈등, 민족과 종교의 차이, 식민지 시대의 국경 획정 같은 역사적 배경 등으로 구분할 수 있다. 영토 분쟁은 특정 지역의 소유권이나 경계선을 두고 국가 간에 벌어지는 갈등으로, 대표적인 사례로 중국과 동남아 국가들 간의 남중국해 영유권 분쟁, 일본과 중국이 갈등하는 센카쿠 열도(댜오위다오) 분쟁, 인도와 파키스탄의 카슈미르 분쟁, 러시아와 우크라이나의 크림반도 분쟁 등이 있다. 영토 분쟁은 단순히 땅의 문제가 아니라 해당 지역에 매장된 자원, 전략적 위치, 역사적 상징성 등이 복합적으로 얽혀 있어 해결이 쉽지 않다. 특히 <b>배타적 경제 수역</b>(EEZ)을 둘러싼 해양 경계 분쟁이 증가하고 있는데, 이는 해저 자원 개발권과 어업권이 걸린 중요한 문제이기 때문이다.',
      '<b>자원 분쟁</b>은 석유, 천연가스, 수자원, 광물 등 한정된 자원을 확보하기 위한 갈등이다. 중동 지역은 풍부한 석유 자원으로 인해 오랫동안 강대국들의 이해관계가 충돌하는 지역이었으며, 아프리카의 콩고민주공화국이나 시에라리온에서는 다이아몬드, 콜탄, 희토류 등 광물 자원을 둘러싼 내전이 발생하기도 했다. <b>수자원 분쟁</b>은 기후 변화와 인구 증가로 더욱 심화되고 있는데, 나일강, 메콩강, 요르단강 유역 국가들 사이에서 물 이용권을 둘러싼 갈등이 대표적이다. 국제하천의 상류 국가가 댐을 건설하면 하류 국가의 수량이 감소하여 농업과 생활용수에 심각한 영향을 미칠 수 있기 때문이다. 북극해 자원을 둘러싼 갈등도 주목되는데, 기후 변화로 북극 빙하가 녹으면서 접근이 쉬워지자 러시아, 미국, 캐나다, 노르웨이, 덴마크 등 연안국들 사이에 자원 개발과 항로 이용권을 둘러싼 경쟁이 치열해지고 있다.',
      '<b>민족 분쟁</b>과 <b>종교 분쟁</b>은 집단 정체성과 관련된 갈등으로, 역사적으로 뿌리가 깊어 해결이 어렵다. 민족 분쟁은 하나의 국가 내에 여러 민족이 거주하거나, 하나의 민족이 여러 국가에 분산되어 있을 때 발생한다. <b>쿠르드족</b>은 터키, 이라크, 이란, 시리아에 걸쳐 분산되어 거주하며 독립국가 수립을 추구하고 있다. 종교 분쟁은 서로 다른 종교나 같은 종교 내 분파 간의 갈등으로, 이스라엘과 팔레스타인 분쟁은 유대교와 이슬람교의 성지 예루살렘을 둘러싼 복잡한 갈등이다. 인도와 파키스탄의 <b>카슈미르 분쟁</b>은 힌두교와 이슬람교의 종교적 차이와 영토 문제가 결합된 사례이다. 이러한 분쟁은 <b>난민</b> 발생, 인권 침해, 경제적 피해 등 심각한 문제를 야기한다.',
      '국제 분쟁 해결을 위해 국제 사회의 다양한 노력이 이루어지고 있다. 1945년 창설된 <b>국제연합</b>(UN)은 분쟁 지역에 <b>평화유지군</b>(PKO)을 파견하고, 당사국 간 협상을 중재하는 역할을 수행한다. 한국군도 레바논, 남수단 등지에 파견되어 활동하고 있다. <b>국제사법재판소</b>(ICJ)는 국가 간 분쟁에 대한 법적 판결을 내리지만, 강제력이 없어 한계가 있다. <b>지역 협력체</b>인 유럽연합(EU), 아프리카연합(AU), 동남아시아국가연합(ASEAN) 등도 지역 내 분쟁 해결에 기여하고 있다. 그러나 국제 분쟁의 근본적 해결을 위해서는 상호 이해와 대화를 통한 평화적 접근이 필수적이다. 학교에서의 <b>다문화 이해 교육</b>, 청소년 교류 같은 민간 외교 활동, 자유무역협정과 같은 경제 협력 증진 등을 통해 갈등의 씨앗을 줄여 나가는 노력이 필요하며, 미래 세대가 평화로운 세계에서 살아갈 수 있도록 국제 사회의 지속적인 관심과 협력, 그리고 시민의 인권 감수성이 함께 요구된다.'
    ],
