      q5: '예시 답안: 첫째, 같은 흡인 요인 앞에서도 어떤 사람은 떠나고 어떤 사람은 머무르며 가족 일부만 분할 이주하는 사례가 있어, push-pull만으로는 결정의 다층성을 설명할 수 없다. 둘째, 신경제이론(NELM)은 이주를 개인의 결정이 아니라 가족 단위의 위험 분산 전략으로 본다. 송금을 통한 본국 위험 대비처럼 push-pull로 잡히지 않는 측면이 분명히 있다. 따라서 push-pull 모델은 출발점이지만 NELM·확장 중력 모델·정책 변수를 함께 결합해야 현실의 인구 이동을 정확히 설명할 수 있다.'
