      q4: '환경 정의의 미래는 단순한 감축만이 아니라 \"감축 + 적응 + 손실과 피해 + 기후 이주민 보호\"의 네 기둥을 통합 설계하는 데에 달려 있다',
      q5: '예시 답안: 첫째, 기후변화의 영향은 지구상에서 매우 불균등하게 분배되며, 온실가스를 많이 배출한 선진국과 가장 큰 피해를 입는 저개발국이 종종 일치하지 않는다. 모두가 똑같은 책임을 지자는 주장은 이러한 구조적 불일치를 외면한다. 둘째, 1992년 UNFCCC의 CBDR 원칙은 모든 나라가 공통 책임을 지되 역사적 배출량과 현재 능력에 따라 차별화되어야 한다고 명시한다. 환경 정의의 미래는 \"감축 + 적응 + 손실과 피해 + 기후 이주민 보호\"의 네 기둥을 통합 설계해야 한다.'
