      q2: '정답: ②번. 2문단은 기후 이주의 지역별 양상을 설명한다.\n\n[오답 풀이]\n①번: 손실과 피해 기금·NDC는 4문단의 내용이다.\n③번: 환경 정의와 CBDR 원칙은 1문단의 내용이다.\n④번: 위험 지도와 SSP 시나리오는 3문단의 내용이다.',
      q3: '정답: ①번. 본문에서 \"위험 지도는 \\\"위험 = 위해(hazard) × 노출(exposure) × 취약성(vulnerability)\\\"의 세 요인을 결합해 지역별 위험을 정량화한다. IPCC AR6 보고서는 공통 사회경제 경로(SSP) 시나리오를 활용해 \\\"SSP1-1.9\\\"',
      q4: '정답: ①번. 본문에서 \"환경 정의의 미래는 단순한 감축만이 아니라 \\\"감축 + 적응 + 손실과 피해 + 기후 이주민 보호\\\"의 네 기둥을 통합 설계하는 데에 달려 있다\"고 설명한다.\n\n[오답 풀이]\n②번: 손실과 피해 기금은 기후 정의의 가장 가시적 성과이다.\n③번: 한국은 OECD 회원국이자 세계 10위권 경제로 새 책임 분담의 한 축이다.\n④번: 디지털 국가는 해수면 상승으로 국토가 위협받는 투발루의 보존 시도이다.'
