        '예시 2: 손실과 피해 기금에 대한 한국의 기여 시나리오와 국제 협력 모델을 ODA·기술 이전·디지털 국가 지원과 결합해 설계한다.',
        '예시 3: 한반도 폭염·해안 침수 위험 지도와 시민 거버넌스 모델을 결합해 \"한국형 기후 회복력 도시 모델\"을 제안한다.'
